import { useState } from "react";
import CoursePage from "./pages/CoursePage";
import AssessmentPage from "./pages/AssessmentPage";
import VideoPage from "./pages/VideoPage";

function App() {
  const [course, setCourse] = useState(null);
  const [questions, setQuestions] = useState(null);
  const [result, setResult] = useState(null);

  if (!course) return <CoursePage setCourse={setCourse} setQuestions={setQuestions} />;
  if (questions && !result) return <AssessmentPage course={course} questions={questions} setResult={setResult} />;
  if (result === "fail") return <h2>Failed the assessment</h2>;
  if (result === "pass") return <VideoPage course={course} />;

  return null;
}

export default App;
